    "description": "The Darjeeling Himalayan Railway, affectionately known as the Toy Train, is a UNESCO World Heritage Site and an engineering marvel. Built in 1881, this narrow-gauge steam railway winds through breathtaking mountain scenery, tea gardens, and quaint hill stations. The iconic journey from Ghum to Darjeeling offers stunning views of valleys, forests, and the Himalayas. Don't miss the ride through the Batasia Loop!",
