    "excerpt": "Spiritual spot with small temples and panoramic views over Darjeeling; popular for short walks from the Mall.",
    "description": "Observatory Hill is Darjeeling's most sacred site, revered by both Hindus and Buddhists. The hill is adorned with colorful prayer flags, bells, and small shrines dedicated to Mahakal (Shiva). The climb rewards visitors with spectacular 360-degree views of Darjeeling town and surrounding mountains. The spiritual atmosphere, combined with scenic beauty, makes it perfect for meditation and photography. Start from the Mall Road for an easy 15-minute walk.",
