    "description": "Chowrasta (The Mall) is the vibrant heart of Darjeeling where locals and tourists converge. This car-free pedestrian square offers stunning Kanchenjunga views on clear days. Lined with bookshops, souvenir stores, wool garment shops, and iconic cafés like Glenary's, it's perfect for leisurely strolls. Street musicians, pony rides, and the buzz of conversation create an unforgettable atmosphere. The Mall connects to Observatory Hill and major hotels.",
