    "description": "Yiga Choeling Monastery, commonly known as Ghum Monastery, is the oldest Tibetan Buddhist monastery in the Darjeeling hills, founded in 1850. Located at India's highest railway station (Ghum), it houses a magnificent 15-foot statue of Maitreya Buddha and precious Tibetan manuscripts. The monastery's peaceful atmosphere, spinning prayer wheels, and butter lamps create a deeply spiritual experience. Monks chanting prayers add to the mystique.",
