    "coordinates": { "lat": 25.2260, "lng": 88.7770 },
    "heroImage": { "url": "https://images.unsplash.com/photo-1622811895178-6e4377539eb3?w=1200", "alt": "Atreyee riverfront near Balurghat with ghats, trees and peaceful water views" },
    "excerpt": "Quiet North Bengal district featuring serene Atreyee river ghats in Balurghat town, heritage museum, peaceful Dhaldighi lake-park, Hili border town market atmosphere, rural village trails through fields and ponds, and authentic small-town Bengal slow-travel charm.",
    "description": "Dakshin Dinajpur offers tranquil small-town experiences centered around Balurghat, the district headquarters nestled along the peaceful Atreyee River. Unlike busier tourist circuits, this region rewards slow travelers with authentic glimpses of everyday Bengal life. The Atreyee riverfront forms the town's spiritual and social heart — ghats where locals perform morning rituals, bathe, and gather for evening conversations create an intimate atmosphere enhanced by riverside promenade stretches and small parks. The Balurghat District Museum houses archaeological treasures, folk art collections, and exhibits documenting local history and cultural evolution, making it a valuable stop for heritage enthusiasts and students. Dhaldighi lake-park provides urban green space with walking tracks, sitting areas and serene water views perfect for families and evening strollers. Scattered through town, clusters of old temples and shrines integrate seamlessly into residential neighborhoods, offering short heritage walking circuits. The real charm lies in venturing beyond town limits — rural villages surrounding Balurghat present classic Bengal landscapes of emerald paddy fields, mirror-like ponds reflecting monsoon skies, traditional homes with courtyards, and friendly villagers going about timeless agricultural rhythms. Weekly haats (village markets) burst with color as locals trade produce, handicrafts, utensils and livestock in open-air gatherings that vary by village and date. For border enthusiasts, Hili town near the Indo-Bangladesh border pulses with unique cross-border trade energy (within regulations), offering bustling markets, colorful shops, and the distinctive atmosphere of an international boundary town. The railway station area serves as a transit hub with its own local character. Throughout the district, small temples, mosques and shrines dot the rural belt, adding layers to the cultural fabric. Riverside tea stalls serve steaming chai with muri and pakoras while locals share stories, family restaurants offer standard Indian-Chinese fare, and highway dhabas provide parathas and thali meals for passing travelers. This is Bengal stripped to its essentials — no flashy attractions, just rivers flowing quietly, markets humming with everyday commerce, fields stretching green to horizons, and the profound peace of places where tourism hasn't yet drowned out local life. Perfect for photographers seeking authentic village scenes, culture travelers appreciating small-town rhythms, and anyone needing a contemplative break between more hectic destinations.",
    "tags": ["Riverfront","TownWalk","Rural","SlowTravel","BorderTown","Museum","Lake","Market","Photography","Village","Heritage","LocalLife","Offbeat","Fields","Temple"],
    "bestTime": "Oct–Mar (comfortable weather)",
