    "heroImage": { "url": "https://images.unsplash.com/photo-1705521680496-d5d7b22c14f7?w=1200", "alt": "Watchtower overlooking mangrove creeks in Sundarbans" },
    "excerpt": "Main forest department complex and watchtower in Sundarbans tourism circuit, with interpretation centre and mangrove view decks.",
    "description": "Sajnekhali serves as the primary entry point and information hub for Sundarbans tourism, featuring a multi-story watchtower offering panoramic views across mangrove canopy and tidal creeks. The interpretation centre provides educational displays about mangrove ecology, tiger conservation, local communities and climate adaptation. A small enclosure houses rescued crocodiles and turtles for close observation. The watchtower deck attracts birdwatchers spotting kingfishers, eagles, herons and occasional rare sightings like masked finfoots. Forest guards maintain a register of tiger movements and wildlife encounters. The facility includes toilets, drinking water and a small canteen. Most guided boat tours include a 1-2 hour stop here, allowing visitors to climb the tower, explore exhibits and purchase local honey or handicrafts from authorized vendors. Early morning arrivals offer best light for photography and wildlife activity. The site demonstrates how tourism can support conservation through permit fees funding protection efforts.",
