    "excerpt": "Historic riverfront town on the Hooghly with promenade, ghats and views of large ships heading to/from the sea.",
    "description": "Diamond Harbour sits strategically where the Hooghly River widens dramatically before meeting the Bay of Bengal, creating a natural deep-water port that has served shipping for centuries. The town's main attraction is its expansive riverfront promenade offering views of cargo vessels, container ships and occasional warships passing through the channel. Historic ghats feature colonial-era steps leading to the water, popular for evening strolls and river contemplation. The town retains British-era architecture in its older quarters, with churches, administrative buildings and bungalows narrating maritime history. Small parks along the river provide picnic spots. The fish market showcases both riverine and sea catches. The town serves as a weekend getaway for Kolkata residents seeking river breezes and open skies. Boat rides can be arranged to mid-river viewpoints. The sunset hour draws locals and visitors to the waterfront where street food vendors sell jhalmuri and tea. The experience is atmospheric rather than activity-packed - perfect for those who enjoy watching river life, ships gliding past, and the timeless rhythm of a port town.",
