    "excerpt": "Main tourist beach with broad promenade, seating, lights and easy access from hotels.",
    "description": "New Digha Sea Beach represents the modernized face of Digha tourism, featuring a well-developed beachfront promenade with concrete walkways, decorative lighting, and organized seating areas. This family-friendly stretch offers safe swimming zones (follow lifeguard instructions), numerous food stalls serving beach snacks, and convenient access to hotels and tourist facilities. The wide sandy expanse accommodates large crowds during peak season, with early mornings offering peaceful walks and spectacular sunrises over the Bay of Bengal. Beach activities include horse rides, camel rides and various water sports through authorized operators. The promenade becomes especially vibrant during evenings when families stroll, children play, and vendors sell everything from puchka to fresh coconut water. Shopping options include small stalls with beach accessories, toys and souvenirs. The area features public toilets, changing rooms and freshwater facilities. The beach's gentle slope makes it suitable for children, though supervision remains essential. New Digha serves as the social hub of the town, where visitors from across Eastern India gather to enjoy sea breezes and coastal culture.",
