    "excerpt": "Rocky stretch with wave breakers, sea views and older lodges; good for sitting and watching waves.",
    "description": "Old Digha Sea Beach offers a contrasting experience to its newer counterpart, featuring a more natural, undeveloped coastline characterized by rocky outcrops and concrete wave breakers. This historic section of Digha retains old-world charm with traditional beach lodges, smaller family-run hotels, and authentic local atmosphere. The rocky terrain creates interesting tidal pools during low tide, fascinating for children and nature observers. Wave breakers provide vantage points for photography enthusiasts capturing dramatic wave crashes and spray. The area suits contemplative visitors who prefer quieter settings over commercial bustle. Local fishing activities can often be observed, with small boats launching through the waves. The beach gradient here is steeper than New Digha, requiring more caution while swimming. Old Digha appeals to budget travelers, repeat visitors nostalgic for Digha's earlier days, and those seeking peaceful sea contemplation. The surrounding neighborhood features older markets, affordable eateries serving authentic Bengali food, and guesthouses with character. Morning walks along the rocky shore offer solitude and connection with nature's raw beauty.",
