    "excerpt": "Small recreational park with boating, children's rides and a ropeway offering elevated views of Digha.",
    "description": "Amravati Park provides family-oriented entertainment combining natural greenery with recreational facilities in the heart of Digha's tourist zone. The park features landscaped gardens, ornamental plants, and shaded sitting areas perfect for relaxing after beach activities. The main attraction is the ropeway (cable car) system offering aerial views across Digha town, beaches, and the Bay of Bengal - particularly spectacular during sunset hours. Children enjoy dedicated play zones with swings, slides and small rides. The boating facility includes paddle boats in an artificial pond, popular for leisurely family outings. The park serves as a green oasis providing respite from beach sand and sun. Evening visits are especially pleasant when cooler temperatures and lighting create romantic ambiance for couples. Food stalls within the park sell snacks, ice cream and beverages. The ropeway ride, though short, provides unique photographic perspectives of the coastal landscape. The park often hosts cultural programs during peak season. Well-maintained pathways make it accessible for elderly visitors and those with limited mobility. The combination of greenery, entertainment and views makes it a must-visit for families with children seeking variety beyond beach activities.",
