    "excerpt": "Beach near a fishing harbour; known for fleets of boats, nets drying on sand and local fish markets.",
    "description": "Shankarpur Sea Beach combines natural beauty with authentic fishing village culture, offering a unique blend of tourism and traditional livelihood. The active fishing harbor dominates the landscape with colorful trawlers, wooden boats pulled up on sand, and fishermen mending nets - creating endless photography opportunities. The beach itself features clean sand and gentler waves compared to more commercial areas. Early morning visits reveal the harbor's busiest hours as boats return with night catches, followed by impromptu fish auctions and market activity. The authentic atmosphere attracts documentary photographers, cultural enthusiasts and travelers seeking genuine coastal experiences. Fresh seafood availability is exceptional, with beach shacks preparing ultra-fresh catches. The village maintains traditional character despite growing tourism interest. Visitors can observe boat-building, net-making and fish-processing activities (respecting local privacy and seeking permission for close photography). The beach area remains relatively less crowded, offering space for relaxation. Sunset views feature silhouetted boats creating dramatic compositions. The community's welcoming nature allows cultural exchange opportunities. Shankarpur demonstrates sustainable tourism where traditional fishing economy coexists with visitor interest, providing economic benefits without overwhelming local culture.",
