    "excerpt": "Beautiful French-built promenade along the Hooghly with heritage lighting and relaxing walks.",
    "description": "The Chandannagar Strand represents one of West Bengal's most charming riverfront promenades, a legacy of French colonial urban planning that continues to enchant visitors. This beautifully maintained walkway stretches along the Hooghly River, featuring ornamental lamp posts, decorative railings, and shaded sitting areas reminiscent of European boulevards. The strand comes alive during evening hours when locals and tourists gather to enjoy river breezes, spectacular sunsets over the water, and the illuminated colonial architecture lining the riverbank. Heritage lighting creates romantic ambiance after dark, with the river reflecting thousands of lights. The promenade serves as a social hub where families stroll, couples relax, street vendors sell snacks, and photographers capture the unique blend of French colonial charm with Bengali river culture. During Jagaddhatri Puja, the strand becomes the center of spectacular illuminated decorations. The walkway offers unobstructed river views, with occasional boat traffic adding to the scenic beauty. Benches positioned along the strand provide perfect spots for contemplation or people-watching. The area demonstrates successful heritage preservation, maintaining its colonial character while serving modern community needs. Nearby colonial buildings add architectural interest to the riverfront vista.",
