    "heroImage": { "url": "https://images.unsplash.com/photo-1564760055775-d63b17a55c44?w=1200", "alt": "Colonial museum building with French heritage exhibits" },
    "excerpt": "Showcases French Bengal history with preserved artifacts, furniture, documents and architecture.",
    "description": "The Chandannagar Museum & Institute preserves and presents the fascinating history of French colonial presence in Bengal, housed in a beautifully maintained colonial-era building. The museum's collection includes authentic period furniture, administrative documents, maps, photographs, and personal belongings from the French colonial era. Exhibits trace Chandannagar's evolution from a French trading post to an important colonial settlement, documenting interactions between French and Bengali cultures. The building itself exemplifies French colonial architecture with high ceilings, arched windows, and elegant proportions. Display rooms recreate period interiors, showing how French administrators and merchants lived. Historical documents include original treaties, trade records, and correspondence. The museum plays a crucial educational role, helping visitors understand this unique chapter of Bengal's multicultural history. Photography enthusiasts appreciate the building's architectural details and well-curated displays. The institute also conducts research and publishes materials on Franco-Bengali cultural exchange. Knowledgeable guides provide context and stories bringing exhibits to life. The museum's location near the Strand allows easy combination with riverfront walks. Well-maintained gardens surround the building, offering pleasant outdoor spaces.",
