    "heroImage": { "url": "https://images.unsplash.com/photo-1609416921929-0e6c7665b0da?w=1200", "alt": "Stunning colonial-era church with stained glass windows" },
    "excerpt": "Stunning church from French colonial era with stained glass and peaceful surroundings.",
    "description": "Sacred Heart Church stands as a magnificent example of French colonial religious architecture in Bengal, serving both spiritual and cultural heritage roles. The church features stunning stained glass windows imported from Europe, depicting biblical scenes in vivid colors that create ethereal light effects inside. The building's architecture combines neo-Gothic and French colonial styles, with pointed arches, tall spires, and ornate decorative elements. The interior maintains a peaceful, contemplative atmosphere with wooden pews, religious statuary, and a beautifully crafted altar. Regular mass services continue, maintaining the church's living spiritual tradition. The surrounding gardens provide serene spaces for quiet reflection. The church played a central role in Chandannagar's French community and continues to serve local Christian populations. Architecture enthusiasts appreciate the building's preservation and authentic period features. The church welcomes visitors of all faiths, though appropriate respect for religious space is expected. Christmas and Easter celebrations feature special decorations and services. The building represents French missionary activity and cultural influence in Bengal. Photography inside requires permission and sensitivity to worship activities. The church's location near the Strand and museum makes it part of Chandannagar's heritage circuit.",
