    "heroImage": { "url": "https://images.unsplash.com/photo-1611312410928-bdcb480e6239?w=1200", "alt": "Iconic riverside clock tower from French colonial era" },
    "excerpt": "Iconic riverside clock tower symbolic of the former French colony era.",
    "description": "The Chandannagar Clock Tower stands as the town's most recognizable landmark, an iconic symbol of French colonial heritage rising prominently along the riverside. Built during the French administration, the tower exemplifies colonial-era public architecture with its distinctive design and prominent clock face visible from considerable distances. The structure combines functional timekeeping with architectural aesthetics, serving as a focal point for the Strand area. The tower's location makes it a natural meeting point and orientation landmark for visitors exploring Chandannagar. The clock mechanism, though requiring periodic maintenance, continues to function, chiming hours and marking time as it has for generations. The tower's base features decorative elements typical of French colonial public monuments. Evening illumination highlights the structure's architectural features, creating a picturesque landmark against the night sky. The tower appears frequently in photographs of Chandannagar, representing the town's unique heritage. The surrounding area serves as a public gathering space, especially during festivals when the tower becomes a backdrop for celebrations. The structure demonstrates the French colonial practice of creating distinctive public landmarks. Its preservation reflects community pride in Chandannagar's multicultural history. The tower's riverside position offers excellent photography opportunities, especially during golden hour.",
