    "heroImage": { "url": "https://images.unsplash.com/photo-1622811895178-6e4377539eb3?w=1200", "alt": "Sacred confluence ghat with river and temples" },
    "excerpt": "Sacred confluence location popular for rituals, fairs and photography.",
    "description": "Tribeni Ghat holds special religious significance as a sacred confluence (sangam) where three rivers traditionally meet, creating an auspicious site for Hindu rituals and ceremonies. The ghat complex features steps leading down to the water, temples, and ritual bathing areas used by pilgrims performing ancestral rites, taking purificatory dips, and conducting religious ceremonies. The site's antiquity is evidenced by ancient temples in the vicinity, including structures dating back several centuries. The name 'Tribeni' (three braids) refers to the confluence, though the exact nature of the river meeting has changed over time due to shifts in river courses. The ghat sees increased activity during auspicious occasions, especially during specific lunar phases and religious festivals. Local priests (pandas) assist pilgrims with ritual procedures. The riverside setting provides peaceful atmospheres for contemplation and prayer. The area attracts photographers interested in capturing religious practices, river life, and atmospheric sunrise/sunset scenes. Annual fairs bring crowds of devotees and create vibrant cultural scenes. The ghat demonstrates living religious traditions continuing over centuries. The surrounding town area includes shops selling puja materials and items needed for rituals. The site offers insights into Hindu ritual practices and the enduring importance of rivers in Indian spiritual life.",
