    "heroImage": { "url": "https://images.unsplash.com/photo-1622811895178-6e4377539eb3?w=1200", "alt": "Ancient riverside ghats with boats and pilgrims" },
    "excerpt": "Riverside steps used for rituals and boat rides connecting Mayapur and nearby spots.",
    "description": "Nabadwip Ghats line the sacred Ganges River, creating an important pilgrimage and cultural landscape associated with Lord Chaitanya's birthplace. These ancient stone steps serve as sites for ritual bathing, religious ceremonies, and daily life along the river. The ghats connect Nabadwip with Mayapur across the river, with boat services operating throughout the day for pilgrims and tourists. The area holds deep significance in Vaishnavite traditions, with numerous temples and ashrams positioned along the riverbank. Morning hours bring devotees for ritual ablutions and prayers as the sun rises over the water. The ghats demonstrate traditional river architecture adapted to seasonal flooding, with varying levels accommodating different water heights. Boat rides offer peaceful perspectives on both riverbanks and opportunities to observe river life, fishing activities, and temple spires. Several ghats bear names associated with religious history and specific ritual purposes. The riverside atmosphere combines spiritual devotion with everyday activities as locals wash clothes, children play, and vendors sell flowers and puja materials. Photography opportunities abound with colorful boats, pilgrims, temple architecture, and river reflections. The ghats remain active during festivals when thousands gather for ceremonial bathing. Evening arati ceremonies at certain ghats feature devotional lamps floated on the water. The area provides authentic experiences of living river culture and pilgrimage traditions.",
