    "heroImage": { "url": "https://images.unsplash.com/photo-1566614788784-9f63ec3e9c87?w=1200", "alt": "Forest sanctuary with deer and nature trails" },
    "excerpt": "Small reserve forest with deer, birds and nature trails — great for school trips and nature-lovers.",
    "description": "Bethuadahari Wildlife Sanctuary provides a valuable green space and biodiversity conservation area in the otherwise densely populated Nadia district. This compact sanctuary protects sal forest habitat supporting populations of spotted deer, various bird species, and smaller mammals. The forest offers nature trails suitable for educational visits, bird watching, and peaceful walks through shaded woodland. The sanctuary serves important ecological functions including water retention, microclimate regulation, and providing wildlife corridors in an agricultural landscape. School groups frequently visit for environmental education programs and nature studies. The forest demonstrates successful community-based conservation in a human-dominated landscape. Bird watchers can observe both resident forest species and seasonal migrants. The trails vary in difficulty, with some accessible to families with children while others offer more challenging terrain for nature enthusiasts. Morning hours provide the best wildlife observation opportunities when animals are most active. The sanctuary maintains visitor facilities including entry points, basic paths, and information signage. The forest's compact size allows thorough exploration in a few hours, making it suitable for half-day excursions. The area offers respite from urban environments for residents of nearby towns. Photography opportunities include forest scenery, deer sightings, and bird species. The sanctuary contributes to environmental awareness and appreciation of local natural heritage.",
    "tags": ["Forest","Wildlife","Family","Nature","Education","BirdWatching","Deer","EcoTourism"],
    "bestTime": "Oct–Mar; early morning for wildlife",
