    "heroImage": { "url": "https://images.unsplash.com/photo-1622811895178-6e4377539eb3?w=1200", "alt": "Peaceful riverfront with boats and views across to Mayapur" },
    "excerpt": "Calm riverfront opposite Mayapur, used for walks and boat rides.",
    "description": "Swarupganj Riverside offers a peaceful riverfront experience directly across the Ganges from the bustling Mayapur ISKCON Temple complex. This less-developed bank provides quieter atmospheres for contemplation, river walks, and observing the spiritual landscape from a different perspective. The riverfront features ghats, boat landing areas, and pathways along the water where visitors can enjoy gentle breezes and river views. The location offers excellent vantage points for photographing Mayapur's temple domes and buildings across the river, especially during sunrise and sunset when lighting creates beautiful reflections. Local boat operators provide river crossing services and leisurely boat rides along the Ganges. The area retains a more rural, traditional character compared to the developed Mayapur side, offering authentic glimpses of riverside village life. Fishermen work along the banks, and local residents use the ghats for bathing and daily activities. The peaceful environment appeals to those seeking quiet reflection away from crowded pilgrimage areas while remaining close to Mayapur's spiritual attractions. The riverside supports small tea stalls and snack vendors serving simple refreshments. Morning hours bring particularly serene atmospheres with mist rising from the water and temple bells audible across the river. The area demonstrates the Ganges' role as a living cultural and ecological system supporting diverse communities.",
