    "excerpt": "Cooperative selling handicrafts, leather-work, batik and local products from Birbhum and nearby areas.",
    "description": "Amar Kutir functions as both a crafts cooperative and showcase for traditional and contemporary handicrafts from Birbhum and surrounding regions. Established to support local artisans and provide marketing channels for their products, the center offers visitors opportunities to purchase authentic handcrafted items at fair prices. The extensive collection includes leather goods (bags, wallets, footwear) crafted using traditional techniques, batik textiles featuring intricate designs and natural dyes, dokra metal castings, terracotta items, handmade paper products, and diverse handicrafts representing Bengal's rich craft traditions. The cooperative model ensures artisans receive equitable compensation while maintaining quality standards. Visitors can observe some craft demonstrations and learn about production processes. The center's shop provides fixed-price, reliable shopping experiences, making it popular with tourists seeking authentic souvenirs without bargaining hassles. The attached cafe serves light refreshments in pleasant surroundings. Amar Kutir plays important roles in preserving traditional skills, providing sustainable livelihoods for rural artisans, and promoting appreciation for handcrafted products. The peaceful campus-like setting makes shopping enjoyable rather than overwhelming. The center also conducts workshops and training programs supporting craft development. Items range from affordable small souvenirs to premium artistic pieces.",
