    "heroImage": { "url": "https://images.unsplash.com/photo-1559827260-dc66d52bef19?w=1200", "alt": "Historic lake and palace remains with garden surroundings" },
    "excerpt": "Historic area with a lake, old palace remains and early British administrative structures.",
    "description": "Motijheel represents a fascinating blend of Nawabi leisure and early British colonial administration, centered around a horseshoe-shaped lake created in the early 19th century. The name 'Motijheel' (Pearl Lake) suggests the beauty that once characterized this area. The site originally featured a palace built by Nawab Nazim of Bengal for his family's recreation, with the lake serving as the centerpiece of landscaped gardens. Following British takeover of administrative functions, parts of the complex were adapted for British use, hence the alternative name 'Company Bagh' (Company Garden). The remaining structures show architectural elements from both Nawabi and early British colonial periods, creating an interesting historical layering. Though the palace now stands in partial ruins, the basic structure and some architectural details remain visible, allowing visitors to imagine the original grandeur. The lake continues to provide scenic beauty, especially during early morning and evening hours when light creates beautiful reflections. The surrounding gardens, though less formal than in their heyday, offer pleasant walking areas and spots for contemplation. The site sees less tourist traffic than Hazarduari or the Imambara, providing quieter experiences for those interested in exploring lesser-known historical sites. Photography enthusiasts appreciate the combination of architectural ruins, lake views, and garden settings.",
