    "coordinates": { "lat": 23.0200, "lng": 87.2100 },
    "heroImage": { "url": "https://images.unsplash.com/photo-1566614788784-9f63ec3e9c87?w=1200", "alt": "Red-earth sal forest with quiet roads perfect for drives and cycling" },
    "excerpt": "Red-earth forest with sal and other trees, quiet drives and cycling options.",
    "description": "Joypur Forest represents the characteristic sal forest ecosystems of West Bengal's western regions, featuring dense stands of sal (Shorea robusta) trees mixed with other deciduous species creating shaded forest environments. The forest floor's distinctive red laterite soil creates striking color contrasts with green vegetation, especially visible along forest roads and clearings. The area offers peaceful forest driving experiences along maintained roads winding through tree-covered terrain, popular with weekend visitors from Kolkata and nearby cities seeking respite from urban environments. The forest roads suit cycling enthusiasts who appreciate the combination of moderate terrain, shade, and scenic beauty. The sal forests undergo seasonal changes – lush during monsoon, golden-brown in autumn, and somewhat bare during hot summer months when sal trees shed leaves. The forests support diverse wildlife including deer, wild boar, various bird species, and smaller mammals, though dense vegetation limits wildlife sighting opportunities compared to more open habitats. The forest department maintains basic facilities and implements conservation measures to preserve forest integrity while allowing public access. The peaceful, natural environment appeals to those seeking quiet nature experiences, meditation, photography, or simply relaxation away from crowds. The proximity to Bishnupur's heritage sites makes Joypur Forest an ideal addition to temple circuit visits, providing nature balance to cultural sightseeing. The forest drives offer pleasant experiences particularly during early morning or late afternoon when light filters beautifully through tree canopies and temperatures remain comfortable.",
