    "heroImage": { "url": "https://images.unsplash.com/photo-1506905925346-21bda4d32df4?w=1200", "alt": "Ajodhya Hills with rocky slopes, forest and reservoir below" },
    "excerpt": "Low hill range with forests, viewpoints, tribal villages and reservoirs; main nature attraction of Purulia.",
    "description": "Ajodhya Hills represents Purulia's premier natural attraction, offering a low mountain range situated on the edge of the Chotanagpur Plateau with elevations reaching around 700 meters. The hills feature a distinctive landscape of exposed rocky slopes, dry deciduous forests, seasonal streams, and reservoirs creating diverse scenic environments. The area provides welcome relief from Bengal's plains with cooler temperatures, fresher air, and panoramic viewpoints offering vistas across forested hills and distant valleys. The hill range supports various ecosystems from rocky outcrops with specialized plant communities to dense forest patches harboring wildlife including deer, wild boar, peacocks, and diverse bird species. Tribal communities, predominantly Santhal people, inhabit villages scattered across and around the hills, maintaining traditional lifestyles, distinctive architectural styles with decorated houses, and cultural practices including dance, music, and festivals. The hills offer multiple activities for visitors – gentle trekking on forest trails, viewpoint photography especially during sunrise and sunset, birdwatching, and cultural interactions with tribal communities through guided village visits. The Upper and Lower Dams create scenic water bodies reflecting surrounding hills and providing boating opportunities. Bamni Falls adds seasonal waterfall attractions during and after monsoon. The relatively undeveloped nature of Ajodhya Hills appeals to travelers seeking offbeat destinations, nature experiences, and authentic cultural encounters away from commercial tourism zones. The combination of natural beauty, cultural richness, and accessibility from major cities makes Ajodhya Hills increasingly popular for weekend getaways.",
    "tags": ["Hills","Nature","Viewpoint","Trek","Tribal","Forest","Weekend","Photography"],
    "bestTime": "Oct–Mar; post-monsoon for waterfalls, winter for comfort",
