    "heroImage": { "url": "https://images.unsplash.com/photo-1533105079780-92b9be482077?w=1200", "alt": "Colorful Chhau masks in artisan workshops with craftsmen at work" },
    "excerpt": "Village of artisans making famous Purulia Chhau masks; colourful workshops and handicraft shops.",
    "description": "Charida Village serves as the epicenter of Purulia Chhau mask-making traditions, preserving and continuing this unique craft that supports the region's famous Chhau dance performances. The village's artisans create elaborate masks representing various characters from Hindu mythology, folk tales, demons, animals, and abstract figures used in Chhau dance dramas. The mask-making process involves skilled papier-mâché techniques, with artisans building up layers of paper and paste over clay molds, allowing them to dry, then painting them in vibrant colors and adding decorative elements. The finished masks range from delicate human faces to fierce demon visages to elaborate animal forms, each requiring different artistic skills and techniques. Visiting Charida allows observing artisans at work in their home workshops, understanding the production process from basic forms through finished products. The workshops and shops display hundreds of masks in various stages of completion and in diverse styles, creating visually spectacular environments filled with color and creativity. Purchasing masks directly from artisan families ensures fair compensation for their skilled work while acquiring authentic cultural artifacts. The masks serve both functional purposes for actual dance performances and decorative purposes for collectors and those seeking unique souvenirs. The village preserves intergenerational knowledge transfer, with children learning mask-making skills from parents and grandparents, maintaining cultural continuity. Charida represents living cultural heritage where traditional crafts continue to thrive through combination of cultural value and economic viability.",
    "tags": ["Craft","Chhau","Culture","Village","Handicraft","Art","Colorful","MustVisit"],
    "bestTime": "Oct–Apr; during working hours to see artisans",
