    "coordinates": { "lat": 23.2100, "lng": 86.0750 },
    "heroImage": { "url": "https://images.unsplash.com/photo-1564760055775-d63b17a55c44?w=1200", "alt": "Tribal village with decorated mud houses and traditional wall paintings" },
    "excerpt": "Santhal and other tribal villages with traditional homes, painted walls and rural life.",
    "description": "The tribal villages scattered across the Ajodhya Hills area and broader Purulia district preserve distinctive cultural identities, architectural styles, and traditional lifestyles of indigenous communities, predominantly Santhal people. These villages offer opportunities for cultural tourism and authentic encounters with communities maintaining traditions alongside selective modernization. Village architecture features mud-walled houses with thatched or tiled roofs, often decorated with beautiful wall paintings depicting geometric patterns, animals, plants, and symbolic designs reflecting aesthetic sensibilities and cultural beliefs. The villages maintain traditional social organizations with community decision-making, shared labor systems, and collective festivals. Daily life revolves around agriculture, forest gathering, small livestock raising, and increasingly, handicraft production for supplemental income. Cultural practices including music (particularly drum and flute traditions), dance (including influences on Chhau), storytelling, and religious observances (mixing indigenous beliefs with Hindu elements) continue to shape village life. Visiting tribal villages requires respectful approaches, ideally with local guides who can facilitate appropriate interactions, explain cultural contexts, and ensure visits benefit communities rather than disrupting lives or commodifying culture. Many villages welcome visitors interested in genuine cultural exchange, willing to learn about traditions, purchase handicrafts directly from makers, and participate respectfully in appropriate activities. Homestay programs in some villages allow deeper immersion experiences. The villages provide perspectives on indigenous knowledge systems, sustainable living practices, and cultural diversity within West Bengal.",
