    "heroImage": { "url": "https://images.unsplash.com/photo-1559827260-dc66d52bef19?w=1200", "alt": "Purulia town with Saheb Bandh lake and urban-rural mix" },
    "excerpt": "Administrative and transport hub with hotels, markets, Saheb Bandh and connections to hill region.",
    "description": "Purulia Town serves as the administrative headquarters and primary urban center of Purulia district, functioning as the transportation hub and base for tourists exploring the region's attractions. The town provides essential infrastructure including railway connectivity (Purulia Junction station), bus services connecting to various destinations, hotels and guesthouses across budget ranges, restaurants offering diverse cuisines, markets for supplies and souvenirs, and basic services like banks, medical facilities, and communication. The town maintains a semi-urban character blending administrative and commercial functions with proximity to rural areas and natural environments. Saheb Bandh lake within the town provides green space and recreational opportunities for residents and visitors. The town market areas offer insights into regional commerce, local products, handicrafts (including Chhau masks), textiles, agricultural produce, and everyday life in a district town. Purulia serves practical purposes as arrival and departure point for visitors coming by train or long-distance bus, as accommodation base for those preferring town amenities over more rustic hill lodges, and as supply point for provisions before heading to more remote areas. The town also houses institutions related to Chhau dance preservation, cultural centers, and occasionally hosts performances and festivals. While not a major tourist attraction itself, Purulia Town performs important supporting roles in regional tourism while offering glimpses of everyday life in West Bengal's interior districts.",
